--- a/app/shared/unknown_445740.cpp
+++ b/app/shared/unknown_445740.cpp
@@ -352,2 +352,5 @@ // 0x4479F0 SteeringClass::Pursue
-	Vector3 result;
-	result = Pursue(vehicle, target);
+	Vector3 desired = Predict(vehicle, target) - vehicle.Position;
+	desired.Normalize();
+	desired *= MaxSpeed;
+	Vector3 result;
+	Vector3::Subtract(desired, vehicle.Velocity, &result);
